:root {
    --layout-max-width: 100vw;
    --layout-news-columns: none;
    --layout-card-gap: 4rem;
    --layout-card-direction: row;
    --layout-animation-style: orbital-flow;
    --card-width: 400px;
    --card-aspect-ratio: 16 / 9;
}

#news-container {
    display: flex;
    flex-direction: var(--layout-card-direction);
    gap: var(--layout-card-gap);
    padding: 0 calc(50vw - var(--card-width) / 2);
    overflow-x: auto;
    overflow-y: hidden;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
    perspective: 2000px;
    align-items: center;
    height: 80vh;
    mask-image: linear-gradient(to right, transparent, black 20%, black 80%, transparent);
}

