    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 24px;
    scroll-snap-align: center;
    transition: all 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);

    /* View Timeline for 3D Animation */
    view-timeline: --card-visible-area inline;
    animation: orbital-rotate linear both;
    animation-timeline: --card-visible-area;
